class CXSignalWatcher;
class CXTradingSessionPool;
class ICXContext;

class CXAppService : public ICXAppService {
private:
    ICXConfig*            m_config;
    IDatabase*            m_db;
    IRepository*          m_repo;
    CXSignalWatcher*      m_watcher;
    CXTradingSessionPool* m_sessionPool;
    ICXContext*           m_globalContext;

public:
    CXAppService(ICXConfig* config, int poolSize = 50);
    virtual ~CXAppService();

    //-- 세션 제어 API
    CXTradingSession* StartSession(ICXParam* param);

    /**
     * @brief 매 틱 주기적 업데이트 (Watcher 및 활성 세션 Pulse)
     */
    void Pulse() {
        CXParam xp; // 기본 틱 페이로더

        // 1. 신호 감시 시퀀스 구동
        if(IS_VALID(m_watcher)) m_watcher.Pulse(GetPointer(xp));

        // 2. 활성 세션 시퀀스 구동 (Pool 내부 순회)
        if(IS_VALID(m_sessionPool)) m_sessionPool.Pulse(GetPointer(xp));
    }

    /**
     * @brief 터미널 트랜잭션 이벤트 전파
     */
    void OnTradeTransaction(const MqlTradeTransaction& trans, const MqlTradeRequest& request, const MqlTradeResult& result) {
        // 특정 SID/Ticket에 해당하는 세션을 찾아 이벤트 전달 로직
    }
};

