    XE_PENDING_PLACED   = 1,
    XE_EXECUTED         = 10,
    XE_CLOSED_SIGNAL    = 20,
    XE_CLOSED_TP        = 21,
    XE_CLOSED_SL        = 23,
    XE_CLOSED_MANUAL    = 24,
    XE_ERROR            = 99
};

//--- 세션 상태 및 시퀀스 단계 정의 (Sequence States)
enum ENUM_SESSION_STATE {
    SESSION_READY          = 0,
    STATE_ENTRY_TRAILING   = 5,
    SESSION_ACTIVE         = 10,
    STATE_EXIT_TRAILING    = 15,
    SESSION_LIQUIDATING    = 20,
    STATE_EXIT_SWEEP       = 21,
    STATE_EXIT_VERIFY      = 22,
    SESSION_CLOSED         = 30,
    SESSION_ERROR          = 99
};

