#ifndef CXCONFIG_MQH
#define CXCONFIG_MQH

#include "..\Interfaces\ICXConfig.mqh"
#include <Arrays\ArrayLong.mqh>

class CXConfig : public ICXConfig {
private:
    string         m_targetMagics;
    CArrayLong     m_magicList;
    double         m_timerInterval;
    string         m_remoteHost;
    int            m_remotePort;

    void ParseMagics(string csv) {
        m_magicList.Clear();
        string parts[];
        int count = StringSplit(csv, ',', parts);
        for(int i=0; i<count; i++) {
            string trim = parts[i];
            StringTrimLeft(trim);
            StringTrimRight(trim);
            if(trim != "") m_magicList.Add(StringToInteger(trim));
        }
    }

    void ParseRemoteAddr(string addr) {
        m_remoteHost = "127.0.0.1";
        m_remotePort = 8787;
        string parts[];
        if(StringSplit(addr, ':', parts) == 2) {
            m_remoteHost = parts[0];
            m_remotePort = (int)StringToInteger(parts[1]);
        }
    }

public:
    CXConfig(string magics, double timer_sec, string remote_addr) {
        m_targetMagics = magics;
        m_timerInterval = timer_sec;
        ParseMagics(magics);
        ParseRemoteAddr(remote_addr);
    }

    virtual ~CXConfig() {}

    // ICXConfig Implementation
    virtual string GetTargetMagics() const { return m_targetMagics; }

    virtual bool IsTargetMagic(long magic) const {
        for(int i=0; i<m_magicList.Total(); i++) {
            if(m_magicList.At(i) == magic) return true;
        }
        return false;
    }

    virtual double GetTimerInterval() const { return m_timerInterval; }
    virtual string GetRemoteLogHost() const { return m_remoteHost; }
    virtual int    GetRemoteLogPort() const { return m_remotePort; }
};

#endif

