        if(IS_VALID(m_logger)) {
            // Watcher ?꾩슜 濡쒓렇 ?뚯씪 珥덇린??
            CXFileLogger* fileLog = new CXFileLogger();
            if(IS_VALID(fileLog)) {
                fileLog.Init("SignalWatcher");
                m_logger.SetFileLogger(fileLog);
            }
            m_ctx.Set("logger", m_logger);
        }

        m_sequence = new CXFluentSequence(m_ctx, "WatcherSeq");
        InitSequence();

        if(IS_VALID(m_logger)) m_logger.Dispatch(LOG_LVL_INFO, ">>> Signal Watcher Started <<<");
    }

    ~CXSignalWatcher() {
        SAFE_DELETE(m_sequence);
        SAFE_DELETE(m_logger);
        SAFE_DELETE(m_ctx);
