    if(IS_INVALID(m_repo)) return;

    // 인터페이스 타입으로 할당
    m_watcher = new CXSignalWatcher(m_repo, m_config);
    if(IS_INVALID(m_watcher)) return;

    m_sessionPool = new CXTradingSessionPool(poolSize);
    if(IS_INVALID(m_sessionPool)) return;

    m_sessionPool.Initialize(m_repo, m_globalContext);
}

