        m_pool.Clear();
        m_active.Clear();
    }

    /**
     * @brief EA 초기화 시 지정된 개수만큼 샌드박스 세션 미리 생성 (Warm-up)
     */
    virtual void Initialize(IRepository* globalRepo, ICXContext* globalContext) {
        for(int i = 0; i < m_initialCount; i++) {
            // 각 세션은 고유의 자원(DB, Log 등)을 가질 수 있도록 리포지토리를 통해 생성 권장
            CXTradingSession* session = new CXTradingSession(globalRepo, globalContext);
            if(IS_VALID(session)) {
                m_pool.Add(session);
            }
        }
    }

    /**
     * @brief 풀에서 유휴 세션 획득 (Borrow)
     */
    virtual CXTradingSession* BorrowSession() {
        if(m_pool.Total() <= 0) return NULL; // 또는 추가 생성 로직

        CXTradingSession* session = (CXTradingSession*)m_pool.Detach(0);
        m_active.Add(session);
        return session;
    }

    /**
     * @brief 사용이 끝난 세션을 풀로 반환 (Return)
     */
    virtual void ReturnSession(CXTradingSession* session) {
        for(int i = 0; i < m_active.Total(); i++) {
            if(m_active.At(i) == session) {
                m_active.Detach(i);
                session.Reset(); // 상태 초기화 후 반환
                m_pool.Add(session);
                break;
            }
        }
    }

    /**
     * @brief 활성 세션들에 대해 주기적 로직(Pulse) 실행
     */
    virtual void Pulse(ICXParam* xp) {
        for(int i = 0; i < m_active.Total(); i++) {
            CXTradingSession* session = (CXTradingSession*)m_active.At(i);
            if(IS_VALID(session)) session.Pulse(xp);
        }
        PurgeClosed();
    }

    /**
     * @brief 종료된 세션을 감지하여 풀로 반환
     */
    void PurgeClosed() {
        for(int i = m_active.Total() - 1; i >= 0; i--) {
            CXTradingSession* session = (CXTradingSession*)m_active.At(i);
            if(IS_VALID(session) && !session.IsActive()) {
                ReturnSession(session);
            }
        }
    }
};

#endif

