#ifndef CXGUARD_MQH
#define CXGUARD_MQH

#include "..\Interfaces\IXGuard.mqh"
#include "..\Interfaces\ICXConfig.mqh"
#include "..\Interfaces\ICXContext.mqh"
#include "..\Interfaces\CXDefine.mqh"

class CXGuard : public IXGuard {
private:
    ICXContext* m_ctx;
    mutable string m_lastError;

    bool SetError(string msg) const { m_lastError = msg; return false; }

public:
    CXGuard(ICXContext* ctx) : m_ctx(ctx) { m_lastError = ""; }
    virtual ~CXGuard() {}

    // Identification Validation
    virtual bool ValidateMagic(long magic) const {
        ICXConfig* config = CX_GET_OBJ(m_ctx, "config", ICXConfig);
        if(IS_INVALID(config)) return SetError("Config not found for Magic validation");
        if(!config.IsTargetMagic(magic)) return SetError("Magic Number " + IntegerToString(magic) + " is not registered");
        return true;
    }

    virtual bool ValidateSID(string sid) const {
        if(StringLen(sid) != SID_MAX_LENGTH) return SetError("Invalid SID length: " + sid);
        // Additional format check (CNO-YYMMDDHH-SNO-GNO-DIR-TYPE)
        return true;
    }

    virtual bool ValidateGID(string gid) const {
        if(StringLen(gid) != GID_MAX_LENGTH) return SetError("Invalid GID length: " + gid);
        return true;
    }

    // Trading Metric Validation
    virtual bool ValidatePrice(string symbol, double price) const {
        if(price <= 0) return SetError("Price must be positive");
        double min_p = SymbolInfoDouble(symbol, SYMBOL_PRICE_LIMIT_MIN);
        double max_p = SymbolInfoDouble(symbol, SYMBOL_PRICE_LIMIT_MAX);
        if(min_p > 0 && price < min_p) return SetError("Price below limit: " + DoubleToString(min_p));
        if(max_p > 0 && price > max_p) return SetError("Price above limit: " + DoubleToString(max_p));
        return true;
    }

    virtual bool ValidateLot(string symbol, double lot) const {
        double min_v = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MIN);
        double max_v = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MAX);
        double step  = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);
        if(lot < min_v) return SetError("Lot below minimum: " + DoubleToString(min_v));
        if(lot > max_v) return SetError("Lot above maximum: " + DoubleToString(max_v));
        // Step check: (lot - min) % step == 0
        return true;
    }

    virtual bool ValidateSlippage(int slippage) const {
        if(slippage < 0 || slippage > MAX_SLIPPAGE) return SetError("Slippage out of range (0-" + IntegerToString(MAX_SLIPPAGE) + ")");
        return true;
    }

    // String & Protocol Validation
    virtual bool ValidateComment(string comment) const {
        if(StringLen(comment) > COMMENT_MAX_LENGTH) return SetError("Comment too long (max " + IntegerToString(COMMENT_MAX_LENGTH) + " chars)");
        return true;
    }

    virtual bool ValidateCnoBinding(int cno, long magic) const {
        if((long)cno != magic) return SetError("CNO-Magic Mismatch: CNO=" + IntegerToString(cno) + ", Magic=" + IntegerToString(magic));
        return true;
    }

    virtual string GetLastError() const { return m_lastError; }
};

#endif

