class CXFluentSequence : public ICXFluentSequence {
private:
    ICXContext*                 m_ctx;
    int                         m_current_state;
    datetime                    m_state_entered;
    CHashMap<int, CXStepNode*>  m_map;
    string                      m_name;
    
