 */
class CXStepEntryTrailingCalc : public IXStep {
public:
    virtual string Name() override { return "Step_EntryTrailingCalc"; }

    virtual bool OnCondition(ICXParam* xp, ICXContext* ctx, int current_state) override {
        CXSignal* sig = dynamic_cast<CXSignal*>(xp.GetSignal());
        return (IS_VALID(sig) && sig.xe_status == XE_PENDING_PLACED && sig.te_start > 0);
    }

    virtual int OnProcess(ICXParam* xp, ICXContext* ctx) override {
        CXSignal* sig = dynamic_cast<CXSignal*>(xp.GetSignal());
        IXPriceTracker* tracker = (IXPriceTracker*)ctx.Get("price_tracker");
        if(IS_INVALID(sig) || IS_INVALID(tracker)) return -1;

        double point = SymbolInfoDouble(sig.symbol, SYMBOL_POINT);
        double currentPrice = SymbolInfoDouble(sig.symbol, (sig.dir == CX_DIR_BUY) ? SYMBOL_BID : SYMBOL_ASK);
        tracker.Update(currentPrice);

        double target = 0;

        // Multi-condition if-else to be reviewed for switch if applicable, 
        // but since it depends on 'dir' and price comparisons, switch is less idiomatic here.
        if(sig.dir == CX_DIR_BUY) {
            target = currentPrice - sig.te_start * point;
            if(target < sig.price_signal - sig.te_step * point) {
                sig.price_signal = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
                return 1; // MODIFIED
            }
        }
        else if(sig.dir == CX_DIR_SELL) {
            target = currentPrice + sig.te_start * point;
            if(target > sig.price_signal + sig.te_step * point) {
                sig.price_signal = NormalizeDouble(target, (int)SymbolInfoInteger(sig.symbol, SYMBOL_DIGITS));
                return 1; // MODIFIED
            }
        }

        return 0; // NO_CHANGE
    }

    virtual void OnEnter(ICXContext* ctx) override {}
    virtual void OnExit(ICXContext* ctx) override {}
};

