interface IXGuard {
    virtual ~IXGuard() {}

    // Identification Validation
    virtual bool ValidateMagic(long magic) const = 0;
    virtual bool ValidateSID(string sid) const = 0;
    virtual bool ValidateGID(string gid) const = 0;

    // Trading Metric Validation
    virtual bool ValidatePrice(string symbol, double price) const = 0;
    virtual bool ValidateLot(string symbol, double lot) const = 0;
    virtual bool ValidateSlippage(int slippage) const = 0;

    // String & Protocol Validation
    virtual bool ValidateComment(string comment) const = 0;
    virtual bool ValidateCnoBinding(int cno, long magic) const = 0;

    // Result Feedback
    virtual string GetLastError() const = 0;
