 */
class CXReverseInjector {
private:
    CXTerminalScanner* m_scanner;
    IRepository*       m_repo;
    ICXContext*        m_ctx;

public:
    CXReverseInjector(IRepository* repo, ICXContext* ctx) 
        : m_repo(repo), m_ctx(ctx) {
        m_scanner = new CXTerminalScanner();
    }
    
    ~CXReverseInjector() {
        SAFE_DELETE(m_scanner);
    }

    /**
     * @brief ??＜???꾨줈?몄뒪 ?ㅽ뻾
     */
    void Execute(CXTradingSessionPool* pool) {
        if(IS_INVALID(pool) || IS_INVALID(m_scanner)) return;

        CArrayObj physicalAssets;
        int found = m_scanner.ScanAll(GetPointer(physicalAssets));
        if(found <= 0) return;

        ICXLogger* logger = (ICXLogger*)m_ctx.Get("logger");

        for(int i = 0; i < physicalAssets.Total(); i++) {
            CXParam* asset = (CXParam*)physicalAssets.At(i);
            string sid = asset.GetString();
            long ticket = asset.GetLong();
            int type = asset.GetInt();

            //-- ?꾩옱 ?몄뀡??먯꽌 愿由?以묒씤吏 ?뺤씤
