            XP_LOG_INFO(xp, "[STEP-MONITOR] Exit Command Detected. Moving to LIQUIDATING.");
            return SESSION_LIQUIDATING;
        }

        // 2. 매니저를 통한 포지션 감시 및 사후 관리
        CXPositionManager* posMgr = (CXPositionManager*)ctx.Get("pos_mgr");
        if(IS_VALID(posMgr)) {
            posMgr.Update(xp);
        }
        return -1; // 상태 유지
    }

    virtual void OnEnter(ICXContext* ctx) override {
        XP_LOG_INFO(NULL, "[STEP-MONITOR] Starting Position Monitoring");
    }

    virtual void OnExit(ICXContext* ctx) override {
        XP_LOG_INFO(NULL, "[STEP-MONITOR] Stopping Position Monitoring");
    }
};

