#ifndef CXSIGNALREPOSITORY_MQH
#define CXSIGNALREPOSITORY_MQH

#include "..\Interfaces\IRepository.mqh"
#include "..\Interfaces\IDatabase.mqh"
#include "..\Models\CXSignal.mqh"

class CXSignalRepository : public IRepository {
private:
   IDatabase* m_db;

public:
   CXSignalRepository(IDatabase* db) : m_db(db) {}
   virtual ~CXSignalRepository() {}

   virtual void SaveSignal(ICXSignal* signal) override {
      CXSignal* sig = dynamic_cast<CXSignal*>(signal);
      if(sig == NULL || m_db == NULL) return;

      string sql = StringFormat(
                      "INSERT OR REPLACE INTO signals (sid, gid, cno, sno, gno, symbol, dir, type, lot, xa_entry, xa_exit, xe_status, updated) "
                      "VALUES ('%s', '%s', %d, %d, %d, '%s', %d, %d, %.2f, %d, %d, %d, datetime('now','localtime'))",
                      sig.sid, sig.gid, sig.cno, sig.sno, sig.gno, sig.symbol, sig.dir, sig.type, sig.lot, sig.xa_entry, sig.xa_exit, sig.xe_status
                   );
      m_db.Execute(sql);
   }

   virtual void LoadParam(ICXParam* param) override {
      // Implementation for loading dynamic parameters
   }

   virtual int GetStatusBySid(const string sid) override {
      if(m_db == NULL || sid == "") return -1;
      string sql = StringFormat("SELECT xe_status FROM signals WHERE sid='%s'", sid);
      int handle = m_db.GetHandle();
      int req = DatabasePrepare(handle, sql);
      int status = -1;
      if(req != INVALID_HANDLE) {
         if(DatabaseRead(req)) DatabaseColumnInteger(req, 0, status);
         DatabaseFinalize(req);
      }
      return status;
   }

   virtual bool UpdateStatus(ICXSignal* signal) override {
      CXSignal* sig = dynamic_cast<CXSignal*>(signal);
      if(m_db == NULL || sig == NULL) return false;
      string sql = StringFormat(
                      "UPDATE signals SET xe_status=%d, xe_status_msg='%s', updated=datetime('now','localtime') WHERE sid='%s'",
                      sig.xe_status, sig.xe_status_msg, sig.sid
                   );
      return m_db.Execute(sql);
   }

   /**
    * @brief 활성 상태가 있는 신호 목록 조회 및 객체 매핑
    */
   int LoadActiveSignals(CArrayObj* list) {
      // 1. 가드 클로즈: 유효성 검사 (Early Return)
      if (m_db == NULL || list == NULL) return 0;

      // 2. SQL 쿼리 작성 (SELECT * 적용)
      string sql = "SELECT * FROM signals WHERE (xa_entry > 0 OR xa_exit > 0) AND xa_status != 6";
      int handle = m_db.GetHandle();
      int req = DatabasePrepare(handle, sql);


      if (req == INVALID_HANDLE) {
         m_nlog.Error(__FUNCTION__, "DatabasePrepare failed: " + (string)GetLastError());
         return 0;
      }

      int count = 0;
      while (DatabaseRead(req)) {
         CXSignal* sig = new CXSignal();

         // 3. 컬럼 명칭을 인덱스로 변환하여 대입 (시각적 가독성을 위해 한 줄 처리)
         DatabaseColumnInteger(req, DatabaseColumnIndex(req, "id"), sig.id);
         DatabaseColumnString(req,  DatabaseColumnIndex(req, "sid"), sig.sid);
         DatabaseColumnString(req,  DatabaseColumnIndex(req, "gid"), sig.gid);
         DatabaseColumnString(req,  DatabaseColumnIndex(req, "symbol"), sig.symbol);
         DatabaseColumnInteger(req, DatabaseColumnIndex(req, "dir"), sig.dir);
         DatabaseColumnInteger(req, DatabaseColumnIndex(req, "type"), sig.type);
         DatabaseColumnDouble(req,  DatabaseColumnIndex(req, "lot"), sig.lot);
         DatabaseColumnDouble(req,  DatabaseColumnIndex(req, "price_signal"), sig.price_signal);
         DatabaseColumnDouble(req,  DatabaseColumnIndex(req, "tp"), sig.tp);
         DatabaseColumnDouble(req,  DatabaseColumnIndex(req, "sl"), sig.sl);
         DatabaseColumnInteger(req, DatabaseColumnIndex(req, "te_start"), sig.te_start);
         DatabaseColumnInteger(req, DatabaseColumnIndex(req, "te_step"), sig.te_step);
         DatabaseColumnInteger(req, DatabaseColumnIndex(req, "ts_start"), sig.ts_start);
         DatabaseColumnInteger(req, DatabaseColumnIndex(req, "ts_step"), sig.ts_step);
         DatabaseColumnInteger(req, DatabaseColumnIndex(req, "xa_entry"), sig.xa_entry);
         DatabaseColumnInteger(req, DatabaseColumnIndex(req, "xa_exit"), sig.xa_exit);
         DatabaseColumnInteger(req, DatabaseColumnIndex(req, "xe_status"), sig.xe_status);

         list.Add(sig);
         count++;
      }

      // 4. 리소스 해제 및 결과 반환
      DatabaseFinalize(req);

      if (count > 0) m_nlog.Debug(__FUNCTION__, StringFormat("Loaded %d active signals", count));

      return count;
   }

// 여기 가지 수정 금지


};

#endif


